ValidationRule.errorConditionFormula:
AND(
    NOT(ISNEW()),
    OR(
        PRIORVALUE(Tender_Stage__c) = "Closed Rejected",
        PRIORVALUE(Tender_Stage__c) = "Closed Accepted"
    ),
    NOT(
        OR(
            $Profile.Name = "System Administrator",
            $Profile.Name = "Utkarsh Admin"
        )
    )
)
